// Exact released IUB/5 bridge; not a general SQL/date parser or native .fls reader.
// All inherited compiler kernels and IG/2 helpers are immutable.
#include "ig2_reference.hpp"

static constexpr U IUB_DATE=6,IUB_KEY=18;
static constexpr int64_t IUB_EPOCH_ORDINAL=719163,IUB_MIN_DAY=-719162,IUB_MAX_DAY=2932896;
static const std::string IUB_SQL="SELECT \"IUBLibrary_1\".\"Sh\" AS \"Sh\",   SUM(1) AS \"usr:Number of Records:ok\" FROM \"IUBLibrary_1\" WHERE (CAST(EXTRACT(YEAR FROM \"IUBLibrary_1\".\"DateLastCharged\") AS BIGINT) = 1900) GROUP BY \"IUBLibrary_1\".\"Sh\";\n";
static bool iub_leap(int y){return y%4==0&&(y%100!=0||y%400==0);}
static int iub_month_days(int y,int m){need(y>=1&&y<=9999&&m>=1&&m<=12,"Gregorian year/month domain");static constexpr int d[]={31,28,31,30,31,30,31,31,30,31,30,31};return d[m-1]+(m==2&&iub_leap(y));}
static int64_t iub_year_start(int y){need(y>=1&&y<=10000,"Gregorian ordinal year bound");int64_t n=y-1;return n*365+n/4-n/100+n/400+1;}
static int64_t iub_ordinal(int y,int m,int d){need(d>=1&&d<=iub_month_days(y,m),"Gregorian day domain");int64_t n=iub_year_start(y)+d-1;for(int j=1;j<m;++j)n+=iub_month_days(y,j);return n;}
static int64_t iub_days(int y,int m,int d){return iub_ordinal(y,m,d)-IUB_EPOCH_ORDINAL;}
struct IubCivil{int y,m,d;};
static IubCivil iub_civil(int64_t days){need(days>=IUB_MIN_DAY&&days<=IUB_MAX_DAY,"finite DATE32 admitted range");int64_t ord=days+IUB_EPOCH_ORDINAL;int lo=1,hi=10000;while(lo+1<hi){int mid=lo+(hi-lo)/2;if(iub_year_start(mid)<=ord)lo=mid;else hi=mid;}int d=int(ord-iub_year_start(lo))+1,m=1;while(d>iub_month_days(lo,m)){d-=iub_month_days(lo,m);++m;}return{lo,m,d};}
static void iub_dictionary_domain(const std::vector<std::string>&dict){for(const auto&s:dict){utf8_exact(s);size_t chars=0;for(unsigned char c:s)chars+=(c&0xc0)!=0x80;need(chars<=2,"Sh VARCHAR2 character domain");}}
static void iub_schema(const Table3&t){need(t.meta.size()==2&&t.cs.size()==2,"IUB projected cardinality");U dates=bank_column(t,IUB_DATE),keys=bank_column(t,IUB_KEY);for(U j:{dates,keys})need(t.meta[j].width==32&&t.meta[j].family==5&&t.cs[j].root->kind==CHUNKS,"fixed plain FFOR DATE/code schema");need(t.meta[dates].n==t.meta[keys].n,"IUB projected common rows");}
static void iub_source_domains(const std::string&dir,const std::vector<std::string>&dict){auto meta=metadata3(dir+"/columns.tsv");need(meta.size()==2,"IUB raw projected cardinality");bool date_seen=false,key_seen=false;
 for(const auto&m:meta){need(m.width==32&&m.family==5&&(m.id==IUB_DATE||m.id==IUB_KEY),"fixed IUB raw source schema");date_seen|=m.id==IUB_DATE;key_seen|=m.id==IUB_KEY;auto a=raw(dir,m.id);auto valid=validity3(dir+"/col"+std::to_string(m.id)+".valid.bitmap",m.n);need(a.size()==m.n,"IUB raw source length");
  for(U i=0;i<m.n;++i){bool live=valid3(valid,i);need(live||a[i]==0,"IUB NULL placeholder");if(!m.nullable)need(live,"IUB source NOT NULL");if(live){if(m.id==IUB_DATE){int64_t day=int64_t(a[i])-int64_t(CODE_BIAS);need(day>=IUB_MIN_DAY&&day<=IUB_MAX_DAY,"finite DATE32 source range");}else sql_code(a[i],dict.size());}}}
 need(date_seen&&key_seen,"IUB both source columns");
}
static void iub_verify_domains(const Table3&t,const std::vector<std::string>&dict){for(U j=0;j<t.cs.size();++j){auto a=cache_column<U>(*t.cs[j].root,t.meta[j].n);for(U i=0;i<a.size();++i)if(valid3(t.valid[j],i)){if(t.meta[j].id==IUB_DATE){int64_t d=int64_t(a[i])-int64_t(CODE_BIAS);need(d>=IUB_MIN_DAY&&d<=IUB_MAX_DAY,"finite decoded DATE32 domain");auto c=iub_civil(d);need(iub_days(c.y,c.m,c.d)==d,"DATE32 civil full roundtrip");}else sql_code(a[i],dict.size());}}}
static std::vector<Query3> iub_predicates(){auto lo=lower_signed3(GE,iub_days(1900,1,1),32),hi=lower_signed3(LT,iub_days(1901,1,1),32);lo.query.id=0;hi.query.id=1;lo.query.col=hi.query.col=IUB_DATE;need(lo.constant==-1&&hi.constant==-1,"fixed Gregorian interval ordinary predicates");return{lo,hi};}
static bool iub_interval(U day,const std::vector<Query3>&q){return q[0].query.p.test(day)&&q[1].query.p.test(day);}
static std::string iub_result(const std::vector<std::string>&dict,const std::vector<SqlWide>&groups){need(groups.size()==dict.size()+1,"IUB NULL group slot");std::vector<U>order;for(U i=0;i<dict.size();++i)if(groups[i])order.push_back(i);std::sort(order.begin(),order.end(),[&](U a,U b){return dict[a]<dict[b];});
 std::string s="{\"columns\":[{\"name\":\"Sh\",\"type\":\"VARCHAR\"},{\"name\":\"usr:Number of Records:ok\",\"type\":\"HUGEINT\"}],\"rows\":[";bool first=true;
 auto emit=[&](const std::string&key,SqlWide n){need(n>0,"SUM1 nonempty positive group");if(!first)s+=',';first=false;s+='[';s+=key;s+=',';s+=sql_json(sql_decimal(n));s+=']';};
 if(groups.back())emit("null",groups.back());for(U i:order)emit(sql_json(dict[i]),groups[i]);return s+"]}\n";
}
static int iub_selftest(){uint64_t endpoints=0;need(iub_days(1970,1,1)==0&&iub_days(1,1,1)==IUB_MIN_DAY&&iub_days(9999,12,31)==IUB_MAX_DAY,"DATE epoch/endpoints");need(iub_days(1900,1,1)==-25567&&iub_days(1901,1,1)==-25202,"source fixed1900 interval");need(!iub_leap(1900)&&iub_leap(2000)&&!iub_leap(2100)&&iub_leap(1600),"Gregorian century leap rules");auto qs=iub_predicates();
 for(int y=1;y<=9999;++y)for(int m=1;m<=12;++m)for(int d:{1,iub_month_days(y,m)}){auto days=iub_days(y,m,d);auto c=iub_civil(days);need(c.y==y&&c.m==m&&c.d==d,"all Gregorian month endpoint inverse");need(iub_interval(U(days+CODE_BIAS),qs)==(y==1900),"all month endpoint interval equivalence");++endpoints;}
 uint64_t rejections=0;for(auto date:std::vector<std::array<int,3>>{{1900,2,29},{2100,2,29},{2000,2,30},{0,1,1},{10000,1,1},{1900,0,1},{1900,13,1},{1900,1,0}}){bool rejected=false;try{(void)iub_days(date[0],date[1],date[2]);}catch(...){rejected=true;}need(rejected,"invalid civil date rejection");++rejections;}
 std::vector<std::string>dict={"A","a","\xc3\xa9","e\xcc\x81"};iub_dictionary_domain(dict);std::vector<SqlWide>counts(dict.size()+1,0);counts.back()=2;counts[0]=1;need(iub_result(dict,counts).find("[null,\"2\"]")!=std::string::npos,"selected NULL key SUM1 group");need(iub_result({},std::vector<SqlWide>(1,0)).find("\"rows\":[]")!=std::string::npos,"typed empty group result");
 uint64_t answers=0;for(U n:{1U,63U,64U,65U,1023U,1024U,1031U}){B a((n+63)/64,0),b(a.size(),0),valid(a.size(),0),expected(a.size(),0);for(U i=0;i<n;++i){int64_t day=-25568+int64_t(i%368);bool live=i%11!=0;U biased=live?U(day+CODE_BIAS):0;bit(valid,i,live);bit(a,i,qs[0].query.p.test(biased));bit(b,i,qs[1].query.p.test(biased));bit(expected,i,live&&day>=-25567&&day<-25202);}for(U w=0;w<a.size();++w)a[w]&=b[w]&valid[w];need(a==expected,"two predicate AND NULL/tail fixture");++answers;}
 std::cout<<"{\"iub5_helper_fixtures\":\"PASS\",\"gregorian_month_endpoints\":"<<endpoints<<",\"invalid_civil_rejections\":"<<rejections<<",\"conjunction_tail_cases\":"<<answers<<",\"observed_values_used\":false}\n";return 0;
}
static int iub_entry(int argc,char**argv){need(argc>=2,"IUB5 mode");std::string mode=argv[1];if(mode=="selftest_iub5"){need(argc==2,"IUB helper arity");return iub_selftest();}
 need(mode=="build_iub5"||mode=="verify_iub5"||mode=="query_iub5","IUB5 command");patch_fusion_enabled=true;physical_fill_mode=3;need(compare_mask_available(),"SSE2 availability before kernel");compare_mask_enabled=true;
 if(mode=="build_iub5"||mode=="verify_iub5"){need(argc==4,"IUB build/verify arity");bool building=mode=="build_iub5";std::string dir=building?argv[2]:argv[3],path=building?argv[3]:argv[2];auto start=Clock::now();auto binding=binding3(dir+"/binding.txt");auto dict=sql_dictionary(dir,binding);iub_dictionary_domain(dict);bool empty=sql_empty(dir);
  if(empty){need(dict.empty(),"IUB empty dictionary");sql_empty_encoded(path,binding,building);}else{if(building)iub_source_domains(dir,dict);Table3 t=building?construct3(dir):load3(path,binding);iub_schema(t);if(building){save3(path,t);t=load3(path,binding);}verify3(t,dir);iub_verify_domains(t,dict);}
  std::cout<<"{\"iub5_build_or_verify_ms\":"<<ms(start)<<",\"dictionary_count\":"<<dict.size()<<",\"empty_relation\":"<<(empty?"true":"false")<<"}\n";return 0;
 }
 need(argc==9,"query_iub5 encoded prepared SQL method result bitmap-or-dash metrics");std::string encoded=argv[2],dir=argv[3],method=argv[5];need(sql_file(argv[4])==IUB_SQL,"only exact pinned IUB/5 SQL admitted");need(method=="generic"||method=="expert"||method=="scan_fused"||method=="cache_fused"||method=="packed_code_fused","IUB5 method");
 auto setup=Clock::now();auto binding=binding3(dir+"/binding.txt");auto dict=sql_dictionary(dir,binding);iub_dictionary_domain(dict);bool empty=sql_empty(dir),diagnostic=std::string(argv[7])!="-";Table3 table;Catalog views;U n=0,dates=0,keys=0;std::vector<U>plain_date,plain_key;
 if(empty){need(dict.empty(),"IUB empty dictionary");sql_empty_encoded(encoded,binding,false);}
 else if(method=="packed_code_fused"){table.binding=binding;table.meta=metadata3(dir+"/columns.tsv");need(table.meta.size()==2,"IUB packed cardinality");dates=bank_column(table,IUB_DATE);keys=bank_column(table,IUB_KEY);n=table.meta[dates].n;
  for(const auto&m:table.meta){need(m.width==32&&m.family==5,"fixed packed DATE/code schema");auto valid=validity3(dir+"/col"+std::to_string(m.id)+".valid.bitmap",n);if(!m.nullable)for(U i=0;i<n;++i)need(valid3(valid,i),"IUB packed NOT NULL");table.valid.push_back(std::move(valid));}
  plain_date=raw(dir,IUB_DATE);plain_key=raw(dir,IUB_KEY);need(plain_date.size()==n&&plain_key.size()==n,"IUB packed source lengths");for(U i=0;i<n;++i){need(valid3(table.valid[dates],i)||plain_date[i]==0,"IUB NULL day placeholder");need(valid3(table.valid[keys],i)||plain_key[i]==0,"IUB NULL key placeholder");}
 }else{table=load3(encoded,binding);iub_schema(table);dates=bank_column(table,IUB_DATE);keys=bank_column(table,IUB_KEY);n=table.meta[dates].n;if(method=="generic"||method=="expert")views=make_views(table.cs);}
 double setup_ms=ms(setup);auto start=Clock::now();auto qs=iub_predicates();size_t stride=(size_t(n)+63)/64;std::vector<SqlWide>groups(dict.size()+1,0);B predicate_bank,selected,diag;BankPlan plan;BankCounters counters;uint64_t decoded_blocks=0;double plan_ms=0,cold_decode_ms=0;if(diagnostic)diag.assign(stride,0);
 auto consume=[&](U row,U biased_key){U code=valid3(table.valid[keys],row)?sql_code(biased_key,dict.size()):U(dict.size());++groups[code];if(diagnostic)bit(diag,row,true);};
 auto accepted=[&](U row,U biased_day){return valid3(table.valid[dates],row)&&iub_interval(biased_day,qs);};
 if(n&&(method=="generic"||method=="expert")){auto pt=Clock::now();bank_validate_queries(table,qs);plan=bank_compile(table,qs,views,method);plan_ms=ms(pt);predicate_bank.assign(2*stride,0);bank_execute(plan,views,predicate_bank,stride,true,counters);bank_constants_validity(table,qs,predicate_bank,stride);selected.resize(stride);for(size_t w=0;w<stride;++w)selected[w]=predicate_bank[w]&predicate_bank[stride+w];
  Scratch key_values;for(U off=0;off<n;off+=V){U take=std::min(V,n-off);bool any=false;for(U i=0;i<take;++i)any=any||valid3(selected,off+i);if(!any)continue;decode_bulk(*table.cs[keys].root->children[off/V],key_values);++decoded_blocks;for(U i=0;i<take;++i)if(valid3(selected,off+i))consume(off+i,key_values.d[i]);}
 }else if(n&&method=="scan_fused"){Scratch day_values,key_values;for(U off=0;off<n;off+=V){U take=std::min(V,n-off);decode_bulk(*table.cs[dates].root->children[off/V],day_values);decode_bulk(*table.cs[keys].root->children[off/V],key_values);decoded_blocks+=2;for(U i=0;i<take;++i)if(accepted(off+i,day_values.d[i]))consume(off+i,key_values.d[i]);}}
 else if(n){if(method=="cache_fused"){auto ct=Clock::now();plain_date=cache_column<U>(*table.cs[dates].root,n);plain_key=cache_column<U>(*table.cs[keys].root,n);cold_decode_ms=ms(ct);decoded_blocks=2*((n+V-1)/V);}for(U i=0;i<n;++i)if(accepted(i,plain_date[i]))consume(i,plain_key[i]);}
 // Every selected row contributes literal one, including NULL Sh. At n<=1e6,
 // every group SUM(1) is exact and bounded in signed128; no count-only proxy for
 // a different payload aggregate is substituted for this original query.
 auto result=iub_result(dict,groups);double query_ms=ms(start);auto rss=resident_kib();auto wt=Clock::now();std::ofstream output(argv[6],std::ios::binary);output.write(result.data(),result.size());output.flush();need(bool(output),"IUB complete result write");if(diagnostic){std::ofstream b(argv[7],std::ios::binary);b.write(reinterpret_cast<const char*>(diag.data()),diag.size()*8);b.flush();need(bool(b),"IUB complete diagnostic write");}double output_ms=ms(wt);
 size_t scratch=n?(method=="packed_code_fused"?0:((method=="scan_fused")?2:1)*sizeof(Scratch)):0;std::ofstream metrics(argv[8]);need(bool(metrics),"IUB metrics output");
 metrics<<"{\"method\":"<<sql_json(method)<<",\"setup_ms\":"<<setup_ms<<",\"query_ms\":"<<query_ms<<",\"plan_ms\":"<<plan_ms<<",\"cold_decode_once_ms\":"<<cold_decode_ms<<",\"output_write_ms\":"<<output_ms
  <<",\"rows\":"<<n<<",\"result_bytes\":"<<result.size()<<",\"predicate_bank_bytes\":"<<predicate_bank.size()*8<<",\"selection_bitmap_bytes\":"<<selected.size()*8<<",\"diagnostic_bitmap_bytes\":"<<diag.size()*8<<",\"diagnostic_enabled\":"<<(diagnostic?"true":"false")
  <<",\"plan_owned_capacity_bytes\":"<<bank_plan_bytes(plan)<<",\"aggregate_capacity_bytes\":"<<groups.capacity()*sizeof(SqlWide)<<",\"code_cache_capacity_bytes\":"<<(plain_date.capacity()+plain_key.capacity())*sizeof(U)<<",\"decoder_scratch_nominal_bytes\":"<<scratch
  <<",\"key_and_date_decode_blocks\":"<<decoded_blocks<<",\"predicate_decode_blocks\":"<<counters.decoded<<",\"whole_process_rss_kib\":"<<rss<<",\"compressed_tree_retained\":"<<((method=="packed_code_fused"||empty)?"false":"true")
  <<",\"date_interval_lower_inclusive\":-25567,\"date_interval_upper_exclusive\":-25202,\"lowered_predicates\":2,\"selected_null_keys_grouped\":true,\"sum_literal_one\":true,\"sum_type\":\"HUGEINT\",\"full_result_serialization_charged\":true,\"runtime_sse2\":true,\"empty_relation\":"<<(empty?"true":"false")<<"}\n";metrics.flush();need(bool(metrics),"IUB metrics flush");return 0;
}
static int frozen_iub5_main(int argc,char**argv){try{return iub_entry(argc,argv);}catch(const std::exception&e){std::cerr<<"REJECT: "<<e.what()<<'\n';return 2;}}
